363	async function runGenerateFlow(options: GenerateOptions) {
364	  await configureApiKeyIfProvided(options.key, options.global);
365	  const apiKey = resolveConfiguredApiKey();
366	
367	  if (options.showConfig) {
368	    showConfigStatus();
369	  }
370	
371	  let scanResult: ScanResult | null = null;
372	  if (options.scan || options.ci) {
373	    scanResult = runScanCommand({ ci: options.ci, silent: false });
374	    if ((!scanResult || scanResult.aiFiles.length === 0) && options.ci) {
375	      log.info('CI mode completed with no AI code detected. Exiting without generating documentation.');
376	      return;
377	    }
378	    if (scanResult && scanResult.aiFiles.length === 0 && !options.ci) {
379	      const { proceed } = await inquirer.prompt<{ proceed: boolean }>([
380	        {
381	          type: 'confirm',
382	          name: 'proceed',
383	          message: 'No AI indicators detected. Generate documentation manually?',
384	          default: true
385	        }
386	      ]);
387	      if (!proceed) {
388	        log.info('Documentation generation cancelled.');
389	        return;
390	      }
391	    }
392	  }
393	
394	  const answers = await Questionnaire.runQuestionnaire({ prompt: (questions) => inquirer.prompt(questions) });
395	  log.info('Generating documentation artefacts...');
396	  const aiTips = await generateAITips(answers, apiKey ?? null, scanResult);
397	  const tipSections = extractTips(aiTips);
398	
399	  const { checklist, modelCard, riskFile } = Documents.generateDocuments({
400	    answers,
401	    tips: tipSections
402	  });
403	
404	  fs.writeFileSync('checklist.md', checklist, 'utf8');
405	  fs.writeFileSync('model_card.md', modelCard, 'utf8');
406	  fs.writeFileSync('risk_file.md', riskFile, 'utf8');
407	
408	  log.success('Responsible AI documentation generated.', {
409	    files: DOC_FILENAMES
410	  });
411	
412	  if (options.exportPdf) {
413	    exportDocsAsPdf();
414	  }
415	
416	  if (!apiKey) {
417	    log.warn('AI guidance tips were skipped because no API key is configured.');
418	  }
419	}
