export function generateReport({
  evaluations,
  outputsPath,
  referencesPath,
  generatedAt = new Date().toISOString(),
  thresholds
}) {
  const totalSamples = evaluations.reduce((total, metric) => {
    if (typeof metric.total === 'number') return Math.max(total, metric.total);
    return total;
  }, 0);

  const report = {
    metadata: {
      generatedAt,
      outputsPath,
      referencesPath,
      totalSamples
    },
    metrics: evaluations
  };

  if (thresholds && Object.keys(thresholds).length > 0) {
    const thresholdResults = Object.entries(thresholds).map(([metricId, min]) => {
      const metric = evaluations.find((m) => m.id === metricId);
      const score = metric?.score ?? null;
      const passed = score !== null && score >= min;
      return {
        metric: metricId,
        min,
        score,
        passed
      };
    });

    const allPassed = thresholdResults.every((t) => t.passed);
    report.passed = allPassed;
    report.thresholds = thresholdResults;
  }

  return report;
}

