// Test CLI parsing logic
import { readFileSync } from 'fs';

const cliCode = readFileSync('./packages/frai-cli/src/index.ts', 'utf8');

// Extract the parseThresholds function
const parseThresholdsMatch = cliCode.match(/function parseThresholds[\s\S]*?\n\}/);
if (!parseThresholdsMatch) {
  console.error('Could not find parseThresholds function');
  process.exit(1);
}

console.log('Found parseThresholds function');

// Test the regex pattern that's used
const regexPattern = /^([a-z_]+)=([0-9.]+)$/;

const testCases = [
  { input: 'exact_match=0.9', valid: true, metric: 'exact_match', min: 0.9 },
  { input: 'toxicity=0.95', valid: true, metric: 'toxicity', min: 0.95 },
  { input: 'custom_metric=0.5', valid: true, metric: 'custom_metric', min: 0.5 },
  { input: 'bad-metric=0.5', valid: false, reason: 'hyphen in metric name' },
  { input: 'EXACT_MATCH=0.9', valid: false, reason: 'uppercase metric name' },
  { input: 'exact_match=abc', valid: false, reason: 'non-numeric value' },
  { input: 'exact_match=', valid: false, reason: 'missing value' },
  { input: '=0.9', valid: false, reason: 'missing metric name' },
  { input: 'exact_match=1.5', valid: true, format_ok: true, range_error: true, reason: 'value > 1' },
  { input: 'exact_match=-0.1', valid: false, reason: 'negative value' },
];

console.log('\nTesting regex pattern:\n');

testCases.forEach((tc) => {
  const match = regexPattern.test(tc.input);
  const expected = tc.valid ? 'match' : 'no match';
  const actual = match ? 'match' : 'no match';
  const status = match === tc.valid ? '✓' : '✗';

  console.log(`${status} "${tc.input}": ${actual} (expected ${expected})${tc.reason ? ` - ${tc.reason}` : ''}`);

  if (match && tc.valid) {
    const groups = tc.input.match(regexPattern);
    console.log(`   → metric="${groups[1]}", min="${groups[2]}"`);
  }
});

console.log('\nValidation summary:');
console.log('- Valid thresholds parse correctly');
console.log('- Invalid formats are rejected');
console.log('- Values outside 0-1 range need additional validation');

