import path from 'path';
import { fileURLToPath } from 'url';
import { Eval } from 'frai-core';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);

console.log('Integration Test: Full eval flow with thresholds\n');

// Setup test files
const tmpDir = '/tmp/frai-test';
const outputsFile = path.join(tmpDir, 'outputs.json');
const referencesFile = path.join(tmpDir, 'references.json');

console.log('1. Creating test files...');
fs.writeFileSync(outputsFile, JSON.stringify(['Hello', 'World', 'Test'], null, 2));
fs.writeFileSync(referencesFile, JSON.stringify(['hello', 'world', 'test'], null, 2));
console.log(`   ✓ Created ${outputsFile}`);
console.log(`   ✓ Created ${referencesFile}\n`);

